M=lambda v: ('-' if v<0 else '')+f'${abs(v)/1e6:,.2f}M'
def wr(name,header,rows):
    with open(f'{OUT}/{name}','w',newline='',encoding='utf-8') as f:
        w=csv.writer(f); w.writerow(header); w.writerows(rows)
    print(name,len(rows))
