import re as _re
def _remap(s):
    def f(m):
        nums=sorted(OLD2NEW[int(n)] for n in _re.findall(r'\d+',m.group(0)))
        return ('Opportunity ' if len(nums)==1 else 'Opportunities ')+' and '.join(map(str,nums))
    return _re.sub(r'Opportunit(?:y|ies) \d+(?: and \d+)*',f,s)
